body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background:
    radial-gradient(circle at center, #151515 0%, #080808 55%, #030303 100%);
  font-family: Inter, Arial, sans-serif;
  color: white;
}

/* bell button */

.bell-button {
  position: relative;

  width: 70px;
  height: 70px;

  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 22px;

  background: rgba(255,255,255,0.055);

  backdrop-filter: blur(14px);

  display: flex;
  align-items: center;
  justify-content: center;

  cursor: pointer;

  transition:
    transform 0.25s ease,
    background 0.25s ease,
    box-shadow 0.25s ease;
}

.bell-button:hover {
  transform: translateY(-3px);

  background: rgba(255,255,255,0.09);

  box-shadow:
    0 12px 35px rgba(0,0,0,0.45),
    0 0 30px rgba(255,255,255,0.07);
}

/* bell  */

.bell-icon {
  position: relative;

  width: 30px;
  height: 30px;

  display: flex;
  align-items: center;
  justify-content: center;

  z-index: 2;
}

.bell-icon svg {
  width: 27px;
  height: 27px;

  stroke: #ffffff;
  stroke-width: 1.7;

  stroke-linecap: round;
  stroke-linejoin: round;

  transform-origin: 50% 15%;
}

/* Bell Swing */

.bell-button.ringing .bell-icon svg {
  animation: bellRing 0.8s cubic-bezier(.36,.07,.19,.97);
}

/* count */

.notification-count {
  position: absolute;

  top: -7px;
  right: -8px;

  min-width: 20px;
  height: 20px;

  padding: 0 5px;

  border-radius: 50px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #ff3b30;

  color: white;

  font-size: 11px;
  font-weight: 700;

  border: 2px solid #090909;

  box-shadow:
    0 0 15px rgba(255,59,48,0.5);

  z-index: 5;

  animation: notificationPulse 1.8s infinite;
}

/* sound waves */

.wave {
  position: absolute;

  width: 30px;
  height: 30px;

  border: 1px solid rgba(255,255,255,0.5);

  border-radius: 50%;

  opacity: 0;

  pointer-events: none;
}

/* panel */

.notification-panel {
  position: absolute;

  top: 84px;
  right: 0;

  width: 360px;

  padding: 18px;

  border-radius: 22px;

  background:
    linear-gradient(
      145deg,
      rgba(30,30,30,0.97),
      rgba(10,10,10,0.97)
    );

  border: 1px solid rgba(255,255,255,0.1);

  box-shadow:
    0 30px 80px rgba(0,0,0,0.6),
    0 0 40px rgba(255,255,255,0.03);

  backdrop-filter: blur(25px);

  opacity: 0;

  visibility: hidden;

  transform:
    translateY(-15px)
    scale(0.94);

  transform-origin: top right;

  transition:
    opacity 0.28s ease,
    transform 0.35s cubic-bezier(.16,1,.3,1),
    visibility 0.28s;
}

.notification-panel.open {
  opacity: 1;

  visibility: visible;

  transform:
    translateY(0)
    scale(1);
}

/* panel holder */

.panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  padding: 3px 3px 15px;
}

.close-button {
  width: 30px;
  height: 30px;

  border: 0;

  border-radius: 9px;

  background: rgba(255,255,255,0.06);

  color: #aaa;

  font-size: 20px;

  cursor: pointer;

  transition: 0.2s;
}

/* notf item */

.notification-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.notification-item {
  position: relative;

  display: flex;
  align-items: flex-start;

  gap: 12px;

  padding: 13px;

  border-radius: 15px;

  background: rgba(255,255,255,0.035);

  border: 1px solid transparent;

  cursor: pointer;

  transition:
    transform 0.2s ease,
    background 0.2s ease;
}

.notification-item:hover {
  transform: translateX(3px);

  background: rgba(255,255,255,0.065);

  border-color: rgba(255,255,255,0.07);
}

/* Avatar */

.notification-avatar {
  width: 38px;
  height: 38px;

  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 12px;

  background: rgba(255,255,255,0.08);

  font-size: 16px;
}

/* Unread Dot */

.unread-dot {
  position: absolute;

  top: 17px;
  right: 12px;

  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #ff3b30;

  box-shadow:
    0 0 10px rgba(255,59,48,0.7);

  transition: 0.25s;
}

.mark-read {
  width: 100%;

  margin-top: 12px;

  padding: 11px;

  border: 1px solid rgba(255,255,255,0.08);

  border-radius: 12px;

  background: rgba(255,255,255,0.045);

  color: #aaa;

  font-size: 12px;

  cursor: pointer;

  transition: 0.2s;
}

